create extension if not exists pgcrypto;
create type public.consent_scope as enum ('save_data','ai_explain','share_passport');
create table public.profiles(user_id uuid primary key references auth.users on delete cascade,display_name text,language text not null default 'en',life_stage text,age_range text,last_period date,cycle_length int,discreet_mode boolean not null default false,created_at timestamptz not null default now());
create table public.consents(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,scope public.consent_scope not null,granted boolean not null default false,updated_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(user_id,scope));
create table public.checkins(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,recorded_at date not null default current_date,life_stage text,flow_level text,notes text,medications text[] not null default '{}',created_at timestamptz not null default now());
create table public.checkin_symptoms(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,checkin_id uuid not null references public.checkins on delete cascade,symptom_code text not null,severity int not null check(severity between 0 and 3),duration text,created_at timestamptz not null default now());
create table public.cycles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,start_date date,end_date date,flow_level text,pain_level int,created_at timestamptz not null default now());
create table public.safety_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,checkin_id uuid references public.checkins on delete set null,level text not null,matched_rule_id text not null,rule_version text not null,created_at timestamptz not null default now());
create table public.pattern_results(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,pattern_id text not null,rule_version text not null,evidence_strength text not null,evidence jsonb not null default '[]',missing_information text[] not null default '{}',created_at timestamptz not null default now());
create table public.followups(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,text text not null,due_date date,done boolean not null default false,created_at timestamptz not null default now());
create table public.report_exports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,sections text[] not null,created_at timestamptz not null default now());
create table public.red_flag_rules(id text primary key,version text not null,all_of text[] not null default '{}',any_of text[] not null default '{}',life_stage text,level text not null,message_key text not null,active boolean not null default true,created_at timestamptz not null default now());
create table public.pattern_rules(id text primary key,version text not null,definition jsonb not null,route_to text not null,topics_to_discuss text[] not null default '{}',created_at timestamptz not null default now());
create table public.providers(id uuid primary key default gen_random_uuid(),name text not null,type text not null,area text,city text,languages text[] not null default '{}',cost_band text,facility text,female_doctor boolean not null default false,source text,verified_on date,is_sample boolean not null default true,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['profiles','consents','checkins','checkin_symptoms','cycles','safety_events','pattern_results','followups','report_exports'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for all using (auth.uid() = user_id) with check (auth.uid() = user_id)',t||'_owner',t); end loop; end $$;
alter table public.red_flag_rules enable row level security; alter table public.pattern_rules enable row level security; alter table public.providers enable row level security;
create policy red_flag_read on public.red_flag_rules for select using (true);create policy pattern_read on public.pattern_rules for select using (true);create policy providers_read on public.providers for select using (true);
